import{_ as s,a0 as r,w as f,s as n,ao as u,I as o,x as t,a1 as l,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Calife：一個輕量級的sudo替代品 | LCTT x X-CMD","titleTemplate":false,"description":"Calife：一個輕量級的sudo替代品 | LCTT (201501) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Calife：一個輕量級的sudo替代品 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Calife：一個輕量級的sudo替代品 | LCTT (201501) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201501/20141224 Calife--A lightweight alternative to sudo","title":"Calife：一個輕量級的sudo替代品","tag":"201501","desc":""},"relativePath":"201501/20141224 Calife--A lightweight alternative to sudo.md","filePath":"[post].md"}'),d={name:"201501/20141224 Calife--A lightweight alternative to sudo.md"};function h(p,e,C,m,g,T){const a=r("Link");return f(),n("div",null,[e[13]||(e[13]=u(`<h1 id="calife-一個輕量級的sudo替代品" tabindex="-1">Calife：一個輕量級的sudo替代品 <a class="header-anchor" href="#calife-一個輕量級的sudo替代品" aria-label="Permalink to “Calife：一個輕量級的sudo替代品”">​</a></h1><p>Calife會在登錄為另外一個用户前輸入自己的密碼（如果沒有提供登錄名，默認是登錄為root），在驗證具有正確的權限後，就會切換到該用户及其組身份，並就會執行一個shell。如果 calife 是由 root 執行的，不需要密碼，會執行一個所需的用户ID的shell。</p><p>所用的shell是用户自身所用的，除非在calife.auth配置文件中指定了某個shell。如果在命令列指定了“-”選項，就會讀取該用户的環境文件，該shell就像是一個登錄shell。這和su的慣常用法不同。</p><p>只有在calife.auth中指定的用户才能使用此方法通過calife成為另外一個用户。calife.auth安裝位置處於/etc/calife.auth。</p><h3 id="calife特性" tabindex="-1">Calife特性 <a class="header-anchor" href="#calife特性" aria-label="Permalink to “Calife特性”">​</a></h3><p>這裏給出了一個關於calife特性的擴展列表：</p><ul><li>你可以完整保留你的環境變量和shell別名</li><li>它可以全程記錄會話的開始到結束</li><li>你可以列出每個許可使用calife的用户，那樣，你就可以用户賦予主管權限而不必提供root密碼</li><li>你可以在配置文件中指定哪個組可以使用：只要使用@staff或者%staff，那麼所有staff組中的成員都將具有訪問calife的權限</li><li>通過calife也可以登錄成為那些沒有家目錄或甚至沒有shell的用户。如果你想要成為uucp或者甚至是bin，那會很方便</li><li>你可以讓calife在會話結束時運行一個指定的系統級的腳本（例如，發送一封郵件告知以root身份做了哪些事）</li></ul><h3 id="ubuntu中安裝calife" tabindex="-1">ubuntu中安裝calife <a class="header-anchor" href="#ubuntu中安裝calife" aria-label="Permalink to “ubuntu中安裝calife”">​</a></h3><p>打開終端，然後運行以下命令</p><pre><code>sudo apt-get install calife
</code></pre><h3 id="使用calife" tabindex="-1">使用Calife <a class="header-anchor" href="#使用calife" aria-label="Permalink to “使用Calife”">​</a></h3><h3 id="語法" tabindex="-1">語法 <a class="header-anchor" href="#語法" aria-label="Permalink to “語法”">​</a></h3><pre><code>calife [-] [login]
</code></pre><p>詳情請參與calife手冊頁</p><hr>`,15)),o("p",null,[e[1]||(e[1]=t("via: ",-1)),l(a,{href:"http://www.ubuntugeek.com/calife-a-lightweight-alternative-to-sudo.html"},{default:i(()=>[...e[0]||(e[0]=[t("http://www.ubuntugeek.com/calife-a-lightweight-alternative-to-sudo.html",-1)])]),_:1})]),o("p",null,[e[5]||(e[5]=t("作者：",-1)),l(a,{href:"http://www.ubuntugeek.com/author/ubuntufix"},{default:i(()=>[...e[2]||(e[2]=[t("ruchi",-1)])]),_:1}),e[6]||(e[6]=t(" 譯者：",-1)),l(a,{href:"https://github.com/GOLinux"},{default:i(()=>[...e[3]||(e[3]=[t("GOLinux",-1)])]),_:1}),e[7]||(e[7]=t(" 校對：",-1)),l(a,{href:"https://github.com/wxy"},{default:i(()=>[...e[4]||(e[4]=[t("wxy",-1)])]),_:1})]),o("p",null,[e[10]||(e[10]=t("本文由 ",-1)),l(a,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...e[8]||(e[8]=[t("LCTT",-1)])]),_:1}),e[11]||(e[11]=t(" 原創翻譯，",-1)),l(a,{href:"http://linux.cn/"},{default:i(()=>[...e[9]||(e[9]=[t("Linux中國",-1)])]),_:1}),e[12]||(e[12]=t(" 榮譽推出",-1))])])}const w=s(d,[["render",h]]);export{x as __pageData,w as default};
